IMPLEMENT_TMPDIR="<TMPDIR>"
# Check the codex events file to understand what happened
wc -l "$IMPLEMENT_TMPDIR/codex-impl-transcript.txt.events.jsonl"
# Last few events
tail -5 "$IMPLEMENT_TMPDIR/codex-impl-transcript.txt.events.jsonl" 2>/dev/null | python3 -c "
import sys, json
for line in sys.stdin:
    try:
        d = json.loads(line.strip())
        t = d.get('type','?')
        if t == 'message':
            role = d.get('role','?')
            content = d.get('content','')
            if isinstance(content, list):
                for c in content:
                    if c.get('type') == 'text':
                        print(f'{role}: {c[\"text\"][:200]}')
            elif isinstance(content, str):
                print(f'{role}: {content[:200]}')
        elif t in ['function_call_output','tool_result']:
            print(f'{t}: {str(d)[:200]}')
        else:
            print(f'{t}: {str(d)[:100]}')
    except: pass
" 2>/dev/null || echo "(parse error)"

