            role = d.get('role','?')
            content = d.get('content','')
            if isinstance(content,list):
                for c in content:
                    if isinstance(c,dict) and c.get('type')=='text':
                        print(f'{role}: {c[\"text\"][:200]}')
            else:
                print(f'{role}: {str(content)[:200]}')
        else:
            print(f'{t}: {str(d)[:200]}')
    except Exception as e:
        print(f'parse error: {e}: {repr(line[:100])}')
